FIT_CODE = '[A-Z][A-Za-z]{0,5}[- ]?\\d{2,6}[A-Za-z]{0,3}'
PART_CODE = '[A-Z]{1,4}\\d{3,6}'
FAMILY = re.compile('(?i)\\b(?:every|all|any)\\s+([a-z][a-z]{0,5}[- ]?\\d{1,5})(x{1,4})\\b|\\b([a-z][a-z]{0,5}[- ]?\\d{1,5})(x{1,4})\\s+(?:series|family|range|models?)\\b')
EXCEPT = re.compile('(?i)\\b(?:except|excluding|but not|other than|apart from|save for)\\b')

def _code_key(code: str) -> str:
    return re.sub('[\\s-]+', '', str(code)).lower()

def _codes(text: Any) -> list[str]:
    found = []
    for code in re.findall('\\b' + FIT_CODE + '\\b', str(text or '')):
        key = _code_key(code)
        if re.search('\\d', key) and (not re.search('\\dx+$', key)) and key not in found:
            found.append(key)
    return found

def _families(text: str) -> list[tuple[str, int]]:
    out = []
    for hit in FAMILY.finditer(text):
        stem, wild = (hit.group(1), hit.group(2)) if hit.group(1) else (hit.group(3), hit.group(4))
        out.append((_code_key(stem), len(wild)))
    return out

def _fit_marks(text: Any) -> dict[str, Any]:
    """What a listing's text says about fits: its own part code, its device codes (model number and the names it is
    also sold as), the codes and families it fits, the codes it excludes, other parts' fits it reports, and the part
    page it points to for more."""
    text = str(text or '')
    own = re.search('[\\[(]\\s*(?:part\\s+)?(' + PART_CODE + ')\\s*[\\])]', text, re.I)
    codes: list[str] = []
    for hit in re.finditer('\\bmodel\\s*(?:no\\.?|number|ref\\.?|#)?\\s*[:.]?\\s*(' + FIT_CODE + ')\\b', text, re.I):
        codes += [c for c in _codes(hit.group(1)) if c not in codes]
    for hit in re.finditer('\\b(?:also sold as|also known as|sold also as)\\s+([^.;]+)', text, re.I):
        codes += [c for c in _codes(hit.group(1)) if c not in codes]
    works: list[str] = []
    families: list[tuple[str, int]] = []
    excluded: list[str] = []
    for hit in re.finditer('\\b(?<!not )(?<!never )(?:works with|compatible with|fits|goes with|suits|for use with|designed for)\\s*:?\\s+([^.;]+)', text, re.I):
        if re.search('\\bpart\\s+' + PART_CODE + '\\s+also\\s+$', text[max(0, hit.start() - 40):hit.start()], re.I):
            continue
        phrase = hit.group(1)
        cut_at = EXCEPT.search(phrase)
        keep, rest = (phrase[:cut_at.start()], phrase[cut_at.end():]) if cut_at else (phrase, '')
        works += [c for c in _codes(keep) if c not in works]
        families += [f for f in _families(keep) if f not in families]
        excluded += [c for c in _codes(rest) if c not in excluded]
    also = [(hit.group(1).upper(), _codes(hit.group(2))) for hit in re.finditer('\\bpart\\s+(' + PART_CODE + ')\\s+also fits\\s*:?\\s*([^.;]+)', text, re.I)]
    more = re.search('\\b(?:more|details|see|read)\\s+(?:on|at|under|about)?\\s*(?:the\\s+)?part\\s+(' + PART_CODE + ')', text, re.I)
    return {'own': own.group(1).upper() if own else '', 'codes': codes, 'works': works, 'families': families, 'except': excluded, 'also': also, 'more': more.group(1).upper() if more else ''}

def _fits_code(code: str, works: set[str], families: list[tuple[str, int]], excluded: set[str]) -> bool:
    if code in excluded:
        return False
    if code in works:
        return True
    return any((code.startswith(stem) and len(code) == len(stem) + wild and code[len(stem):].isdigit() for stem, wild in families))

def _dump(value: Any) -> str:
    try:
        return json.dumps(value, ensure_ascii=False, separators=(',', ':'))
    except (TypeError, ValueError):
        return str(value)

def _clip(value: Any, limit: int, depth: int=0) -> Any:
    if depth > 7:
        return '...'
    if isinstance(value, str):
        return value if len(value) <= limit else value[:limit] + '...'
    if isinstance(value, dict):
        return {k: _clip(v, limit, depth + 1) for k, v in value.items()}
    if isinstance(value, list):
        return [_clip(v, limit, depth + 1) for v in value]
    return value

OWN_PLAN = re.compile("(?i)\\bI(?:'ll| will|'m| am|'d| would| can| could)?\\s+(?:just |probably |also |only |then |simply )?(?:(?:want|need|plan|intend|mean|hope|have|got|going) to )?(?:buy|use|order|sort|split|pick|put|pay|fit|hang|share|give|plug|wear|serve|store|place|fix|grab|add|collect|bring|carry|install|mount|arrange|ship|send|post)\\w*\\b|\\bI(?:'ll| will|'m| am|'d| would| can| could)?\\s+(?:just |also |then )?get(?:ting)? (?:them|those|these|it|one|each|the|a|both|all)\\b")
CLAUSE_END = re.compile("[.?!;,]|\\s(?:so|but)\\s")
ONE_AT_A_TIME = re.compile('(?i)\\bone (?:by one|at a time|after (?:another|the other))\\b|\\b(?:a single|just one|only one|just the one|only the one) (?:question|query|ask)\\b|\\b(?:ask|give|put|raise|send|pop)\\b[^.?!]{0,25}\\b(?:a single|just one|only one|just the one|only the one|one) (?:thing|matter|point|topic)\\b|\\b(?:a single|just one|only one|just the one|only the one|one) (?:thing|matter|point|topic) to (?:ask|answer)\\b|\\b(?:just|only) (?:the )?first\\b(?!(?: one| thing)? (?:that|which|who|you|we|i|available|listed)\\b)(?: one| thing| question| query| of (?:those|them|these))?\\b|\\b(?:in|by) turns?\\b|\\bin sequence\\b|\\bseparately\\b|\\bsingly\\b|\\b(?:split|break|space) (?:them|those|these|it|that|the questions)? ?(?:up|out)\\b|\\btoo many (?:questions|things|asks)\\b|\\b(?:too many|too much) (?:\\w+ )?(?:at once|in one go|at the same time)\\b|\\ball at once\\b|\\bin one go\\b|\\bat the same time\\b|\\b(?:the rest|the others) (?:afterwards|after|later)\\b|\\b(?:hold|save|keep) (?:the )?(?:rest|others)(?: back| for later)?\\b(?! (?:of|like))|\\b(?:one|first|single)\\b[^.?!]{0,60}\\b(?:then|before|after)\\b[^.?!]{0,25}\\b(?:the next|another|the rest|the others|move on)\\b')
FIELD_NAME = '[A-Za-z][\\w\\-./()&+#]*(?: [\\w\\-./()&+#]+){0,4}'
FIELD_SPLIT = re.compile('\\s+\\|\\s+(?=' + FIELD_NAME + ':(?:\\s|$))')
ID_VALUE = re.compile('(?=[^\\s]*\\d)(?=[^\\s]*[A-Za-z])[A-Za-z0-9][\\w.\\-]{2,63}')
FIELD_HEAD = re.compile('^\\s*(' + FIELD_NAME + '):\\s?(.*)$', re.S)
PAIR_SPLIT = re.compile(';\\s*(?=[^;=|]{1,60}=)')
WORD_VALUES = {'none': None, 'null': None, 'true': True, 'false': False}
NAME_FIELD = re.compile('(?i)(?:^|[\\s_\\-])(?:title|name|heading|headline|caption|product|item|label|model)s?$')
BLOCK_FIELD = re.compile('(?i)fact|attr|spec|propert|feature|param|detail|characteristic|table|info')
TEXT_FIELD = re.compile('(?i)blurb|desc|about|summary|overview|text|note|title|name|heading|comment|review|story')
LIST_MARK = re.compile('^\\s*(?:\\d{1,3}[.)]|[-*•])\\s+')


def _word_value(text: str) -> Any:
    plain = text.strip()
    return WORD_VALUES[plain.lower()] if plain.lower() in WORD_VALUES else plain


def _unquote(text: str) -> str:
    plain = text.strip()
    return plain[1:-1].strip() if len(plain) >= 2 and plain[0] == plain[-1] and plain[0] in '"\'' else plain


def _pairs(text: str) -> dict[str, Any] | None:
    """'k=v; k=v' (two or more pairs and nothing else) as a dict of texts, else None."""
    if text.count('=') < 2:
        return None
    found: dict[str, Any] = {}
    for part in PAIR_SPLIT.split(text.strip().strip(';')):
        key, sep, value = part.partition('=')
        if not sep or not key.strip() or len(key.strip()) > 60 or key.strip() in found:
            return None
        found[key.strip()] = _unquote(value)
    return found if len(found) >= 2 else None


def _record_of(fields: list[tuple[str, str]]) -> dict[str, Any] | None:
    """Named text fields as a listing record, or None unless a field names the product and a value is an identifier.
    Attribute-block fields (else plain fields that are not titles or descriptions) holding 'k=v; k=v' become dicts."""
    if not any((NAME_FIELD.search(name) and re.search('[A-Za-z]{2}', value) and (not ID_VALUE.fullmatch(value)) for name, value in fields)) or not any((ID_VALUE.fullmatch(value) for _, value in fields)):
        return None
    blocks = {name for name, _ in fields if BLOCK_FIELD.search(name)} or {name for name, _ in fields if not TEXT_FIELD.search(name)}
    row: dict[str, Any] = {}
    for name, value in fields:
        nested = _pairs(value) if name in blocks else None
        row[name] = nested if nested is not None else _word_value(value)
    return row


def _text_row(text: str) -> dict[str, Any] | None:
    """A listing written as 'key: value' fields joined by ' | ' (three or more fields) as a dict; a field name met
    again stays text of the field before it."""
    text = LIST_MARK.sub('', text.strip(), count=1)
    if text.count(' | ') < 2 or ':' not in text[:120]:
        return None
    parts = FIELD_SPLIT.split(text)
    if len(parts) < 3:
        return None
    fields: list[tuple[str, str]] = []
    for part in parts:
        head = FIELD_HEAD.match(part)
        if head and all((head.group(1).strip() != name for name, _ in fields)):
            fields.append((head.group(1).strip(), _unquote(head.group(2))))
        elif fields:
            fields[-1] = (fields[-1][0], fields[-1][1] + ' | ' + part.strip())
        else:
            return None
    return _record_of(fields) if len(fields) >= 3 else None


AMOUNT_TEXT = re.compile('(?<![\\w.])-?\\d{1,3}(?:,\\d{3})+(?:\\.\\d+)?|(?<![\\w.])-?\\d+(?:\\.\\d+)?')
NO_STOCK = re.compile('(?i)\\b(?:out of stock|sold ?out|unavailable|not available|not in stock|no stock|none left|discontinued|no longer (?:available|sold|offered|stocked)|(?:back )?in stock soon|coming soon|back ?order\\w*|pre ?order\\w*)\\b|\\b0+ (?:in stock|available|left)\\b')
STOCK_LEFT = re.compile('(?i)\\bin stock\\b(?! soon)|\\b[1-9]\\d* (?:left|available|in stock)\\b')
STOCK_NEVER = re.compile('(?i)out of stock|not in stock|no stock|in stock soon|coming soon|back ?order|pre ?order|no longer')
PAIR_NAME = re.compile('(?i)^(?:name|key|label|attribute|property|field|spec|feature)$')
PAIR_VALUE = re.compile('(?i)^(?:value|values|val|text|detail|setting)$')
LINE_FIELD = re.compile('^\\s*(?:\\d{1,3}[.)]\\s+|[-*•]\\s+)?([A-Za-z][\\w\\-./()&+# ]{0,40}?)\\s*:\\s*(\\S.*)$')


def _amount(text: str) -> float | None:
    """The number a price text states ("$1,299.00", "12.99 USD", "USD12.99", "1.299 EUR", "was 15.99, now 12.99"), or
    None when it holds none, several, a percentage or a negative number."""
    plain = str(text).strip()
    sale = re.search('(?i)\\b(?:now|sale|offer)\\b[:\\s]*([^,;]*)$', plain)
    if sale and AMOUNT_TEXT.search(sale.group(1)):
        plain = sale.group(1).strip()
    plain = re.sub('\\s*\\([^()]*%[^()]*\\)', '', plain)
    if '%' in plain or len(plain) > 24:
        return None
    plain = re.sub('(?<=[A-Za-z])(?=\\d)|(?<=[A-Za-z]\\.)(?=\\d)', ' ', plain)
    found = AMOUNT_TEXT.findall(plain)
    if len(found) != 1 or found[0].startswith('-'):
        return None
    number = found[0]
    if re.fullmatch('[1-9]\\d{0,2}(?:\\.\\d{3})+', number):
        number = number.replace('.', '')
    return float(number.replace(',', ''))


def _stock_ok(text: str) -> bool:
    """Whether a stock text lets the listing be bought (see the stage notes)."""
    plain = re.sub('[\\-_]+', ' ', str(text)).strip().lower()
    if re.fullmatch('(?:no|none|n|false|0+)(?: (?:left|units?|items?|pcs|in stock|available))?', plain):
        return False
    if NO_STOCK.search(plain):
        return bool(STOCK_LEFT.search(plain)) and (not STOCK_NEVER.search(plain))
    return True


def _pair_list(node: list[Any]) -> dict[str, Any] | None:
    """[{name: k, value: v}, ...] as {k: v} when every entry is such a pair (two or more entries)."""
    if len(node) < 2 or not all((isinstance(v, dict) and len(v) == 2 for v in node)):
        return None
    found: dict[str, Any] = {}
    for entry in node:
        name = next((v for k, v in entry.items() if PAIR_NAME.match(str(k))), None)
        slot = next((k for k in entry if PAIR_VALUE.match(str(k))), None)
        value = entry[slot] if slot is not None else None
        if slot is None or not isinstance(name, str) or not name.strip() or isinstance(value, (dict, list)) or name.strip() in found:
            return None
        found[name.strip()] = value
    return found


def _line_block(text: str) -> dict[str, Any] | None:
    """A text of three or more 'Key: value' lines (nearly every line one) as a dict."""
    lines = [line for line in text.splitlines() if line.strip()]
    if len(lines) < 3:
        return None
    pairs = [LINE_FIELD.match(line) for line in lines]
    if sum((1 for p in pairs if p)) < max(3, 0.75 * len(lines)):
        return None
    block: dict[str, Any] = {}
    for match in pairs:
        if not match:
            continue
        if match.group(1).strip() in block:
            return None
        block[match.group(1).strip()] = _unquote(match.group(2))
    return _record_of(list(block.items()))


NEGATING = {'free', 'non', 'no', 'not', 'without', 'except', 'excluding', 'never'}
KEY_PREFIX = {'attr', 'attribute', 'prop', 'property', 'spec', 'item', 'product', 'p', 'a', 'f', 'fa', 'x'}


def _key_forms(key: Any) -> set[frozenset[str]]:
    """A key's words as _spelled gives them, with and without generic prefix words ("attr_color", "fa-pattern")."""
    words = _spelled(str(key))
    plain = frozenset((w for w in words if w not in KEY_PREFIX))
    return {words, plain} if plain else {words}


def _value_words(text: str) -> set[str]:
    """The words and numbers of a value, lower case, plural s dropped: what a word-for-word match compares."""
    return {re.sub('(?:(?<=ch)|(?<=sh)|(?<=x)|(?<=ss))es$|(?<=[a-z]{2}[^s])s$', '', w) for w in re.findall('\\d+(?:\\.\\d+)?|[a-z]+', str(text).lower())}


def _readable(node: Any, depth: int=0, in_record: bool=False) -> Any:
    """A store reply with its listings as records: text rows, 'Key: value' blocks and JSON strings decoded, lists of
    {name, value} pairs merged, everything else unchanged. In a field of a record (a dict of three or more fields) only
    a text row is read: descriptions often hold 'Key: value' lines that other readers need as text."""
    if depth > 8:
        return node
    if isinstance(node, str) and in_record:
        row = _text_row(node)
        return row if row is not None else node
    if isinstance(node, str):
        plain = node.strip()
        if len(plain) >= 2 and plain[0] in '[{' and plain[-1] in ']}':
            try:
                decoded = json.loads(plain)
            except ValueError:
                decoded = None
            if isinstance(decoded, (dict, list)):
                return _readable(decoded, depth + 1)
        row = _text_row(node)
        if row is None and '\n' in plain:
            row = _line_block(plain)
        return row if row is not None else node
    if isinstance(node, list):
        pairs = _pair_list(node)
        if pairs is not None:
            return {key: _readable(value, depth + 1, True) for key, value in pairs.items()}
        return [_readable(value, depth + 1) for value in node]
    if isinstance(node, dict):
        record = len(node) >= 3
        return {key: _readable(value, depth + 1, record) for key, value in node.items()}
    return node

def _json_obj(text: Any) -> dict[str, Any] | None:
    if not isinstance(text, str):
        return None
    text = text.strip()
    fence = re.match('^```[A-Za-z]*\\s*(.*?)\\s*```$', text, re.S)
    if fence:
        text = fence.group(1)
    try:
        got = json.loads(text)
        return got if isinstance(got, dict) else None
    except ValueError:
        pass
    left, right = (text.find('{'), text.rfind('}'))
    if 0 <= left < right:
        try:
            got = json.loads(text[left:right + 1])
            return got if isinstance(got, dict) else None
        except ValueError:
            return None
    return None

def _turned_back(text: Any) -> bool:
    """Whether a reply asks for questions one at a time: a ONE_AT_A_TIME phrase whose clause does not hold the
    shopper's own plan for the goods ("I'll buy the bulbs separately", "I'm buying the set in one go")."""
    text = str(text or '')
    for hit in ONE_AT_A_TIME.finditer(text):
        start = max([m.end() for m in CLAUSE_END.finditer(text, 0, hit.start())] or [0])
        plan = OWN_PLAN.search(text, start, hit.end())
        if not plan or plan.start() >= hit.start():
            return True
    return False

def _words(key: str) -> str:
    key = re.sub('([a-z0-9])([A-Z])', '\\1 \\2', str(key))
    return re.sub('[\\s_.\\-]+', ' ', key).strip().lower()

def _snake(key: str) -> str:
    return _words(key).replace(' ', '_')

def _stem(text: str) -> frozenset[str]:
    return frozenset((w[:-1] if len(w) > 3 and w.endswith('s') else w for w in _words(text).split()))

def _roots(text: str) -> set[str]:
    out = set()
    for w in _words(text).split():
        w = w[:-2] if re.search('(?:ch|sh|ss|x|z)es$', w) else w[:-1] if len(w) > 3 and w.endswith('s') and (not w.endswith('ss')) else w
        if len(w) >= 3 and w not in ('and', 'for', 'the', 'with'):
            out.add(w)
    return out

def _spelled(text: str) -> frozenset[str]:
    """A name's words with plural -s and British -our folded, so "colours" and "color" compare equal."""
    return frozenset((re.sub('our$', 'or', w[:-1] if len(w) > 3 and w.endswith('s') and (not w.endswith('ss')) else w) for w in _words(text).split()))

def _names(prop: frozenset[str], key: frozenset[str]) -> bool:
    if not prop or not key:
        return False
    return prop == key or prop <= key or (len(key) >= 2 and key <= prop)

def _kinds(schema: dict[str, Any]) -> list[str]:
    kind = schema.get('type')
    if isinstance(kind, str):
        return [kind]
    return [k for k in kind or [] if isinstance(k, str)]

def _fits_kind(value: Any, kind: str) -> bool:
    if kind == 'string':
        return isinstance(value, str)
    if kind == 'integer':
        return isinstance(value, int) and (not isinstance(value, bool))
    if kind == 'number':
        return isinstance(value, (int, float)) and (not isinstance(value, bool))
    if kind == 'boolean':
        return isinstance(value, bool)
    if kind == 'array':
        return isinstance(value, list)
    if kind == 'object':
        return isinstance(value, dict)
    if kind == 'null':
        return value is None
    return True

def _shape(value: Any, schema: Any, where: str, faults: list[str]) -> Any:
    if not isinstance(schema, dict):
        return value
    kinds = _kinds(schema)
    if kinds and (not any((_fits_kind(value, k) for k in kinds))):
        for kind in kinds:
            if kind == 'integer' and isinstance(value, float) and value.is_integer():
                value = int(value)
                break
            if kind in ('integer', 'number') and isinstance(value, str) and re.fullmatch('\\s*-?\\d+(\\.\\d+)?\\s*', value):
                number = float(value)
                value = int(number) if kind == 'integer' or number.is_integer() else number
                break
            if kind == 'string' and isinstance(value, (int, float)) and (not isinstance(value, bool)):
                value = str(value)
                break
            if kind == 'boolean' and isinstance(value, str) and (value.strip().lower() in ('true', 'false')):
                value = value.strip().lower() == 'true'
                break
            if kind == 'array' and (not isinstance(value, list)) and (value is not None):
                value = [value]
                break
        if not any((_fits_kind(value, k) for k in kinds)):
            faults.append(f"{where} should be {'/'.join(kinds)}")
            return value
    options = schema.get('enum')
    if isinstance(options, list) and value not in options:
        if isinstance(value, str):
            low = value.strip().lower()
            match = [o for o in options if isinstance(o, str) and o.lower() == low]
            if match:
                value = match[0]
        if value not in options:
            faults.append(f'{where}: allowed values are {options}')
    if isinstance(value, str) and isinstance(schema.get('maxLength'), int) and (len(value) > schema['maxLength']):
        value = value[:schema['maxLength']]
    if isinstance(value, str) and isinstance(schema.get('minLength'), int) and (len(value) < schema['minLength']):
        faults.append(f'{where} is too short')
    if isinstance(value, (int, float)) and (not isinstance(value, bool)):
        if isinstance(schema.get('minimum'), (int, float)) and value < schema['minimum']:
            faults.append(f"{where} is below {schema['minimum']}")
        if isinstance(schema.get('maximum'), (int, float)) and value > schema['maximum']:
            faults.append(f"{where} is above {schema['maximum']}")
    if isinstance(value, list):
        if isinstance(schema.get('maxItems'), int) and len(value) > schema['maxItems']:
            faults.append(f"{where} allows at most {schema['maxItems']} entries")
        if isinstance(schema.get('minItems'), int) and len(value) < schema['minItems']:
            faults.append(f"{where} needs at least {schema['minItems']} entries")
        if isinstance(schema.get('items'), dict):
            value = [_shape(v, schema['items'], f'{where}[{i}]', faults) for i, v in enumerate(value)]
    if isinstance(value, dict):
        props = schema.get('properties') if isinstance(schema.get('properties'), dict) else {}
        if schema.get('additionalProperties') is False:
            for name in [n for n in value if n not in props]:
                faults.append(f'{where}.{name} is not an allowed argument')
        for name in schema.get('required') or []:
            if name not in value:
                faults.append(f'{where}.{name} is required')
        value = {k: _shape(v, props.get(k), f'{where}.{k}', faults) if k in props else v for k, v in value.items()}
    return value

def _items(value: Any) -> list[Any]:
    if isinstance(value, list):
        return value
    if isinstance(value, (str, dict)) and value:
        return [value]
    return []

def _count(value: Any) -> int | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, float) and value.is_integer():
        return int(value)
    if isinstance(value, str) and re.fullmatch('\\s*\\d+(\\.0+)?\\s*', value):
        return int(float(value))
    return None

def _id_like(value: Any, named: bool=False) -> bool:
    if not isinstance(value, str) or not 3 <= len(value.strip()) <= 64 or ' ' in value.strip():
        return False
    return named or bool(re.search('\\d', value))

def _learn_id(rows: list[dict[str, Any]]) -> str | None:
    best = None
    for key in rows[0]:
        values = [row.get(key) for row in rows]
        if not all((_id_like(v, 'id' in str(key).lower()) for v in values)):
            continue
        values = [v.strip() for v in values]
        if len(rows) > 1 and len(set(values)) < len(values):
            continue
        score = ('id' in str(key).lower(), sum((len(v) for v in values)) / len(values))
        if best is None or score > best[0]:
            best = (score, key)
    return best[1] if best else None

def _in_rows(node: Any, ident: str, depth: int=0) -> bool:
    if depth > 5:
        return False
    if isinstance(node, list):
        return any((isinstance(v, dict) and ident in [str(x).strip() for x in v.values() if isinstance(x, str)] for v in node)) or any((_in_rows(v, ident, depth + 1) for v in node))
    if isinstance(node, dict):
        return any((_in_rows(v, ident, depth + 1) for v in node.values()))
    return False

def _llm_within(seconds: float) -> ProxyClient:
    """The model client whose timeout fits the time left: the usual one, or one with a timeout in whole 5 s steps."""
    if seconds >= 50:
        return _llm
    limit = max(5, int(seconds) // 5 * 5)
    if limit not in _llm_short:
        _llm_short[limit] = ProxyClient(timeout=limit, max_retries=1, retry_delay=1)
    return _llm_short[limit]

def _fact_block(node: Any) -> dict[str, Any] | None:
    if not isinstance(node, dict):
        return None
    best = None
    for value in node.values():
        if isinstance(value, dict) and len(value) >= 2:
            scalars = {k: v for k, v in value.items() if isinstance(v, (str, int, float)) and (not isinstance(v, bool))}
            if len(scalars) >= 2 and (best is None or len(scalars) > len(best)):
                best = scalars
    return best

class Item:

    def __init__(self, name: str, shelf: str, qty: int, musts: list[str]):
        self.name = name
        self.shelf = shelf
        self.qty = qty
        self.musts = musts
        self.told: list[str] = []
        self.dropped: list[str] = []
        self.free: list[str] = []

class Sparrow:

    def __init__(self, problem: dict[str, Any]):
        environment = problem['environment']
        self.binding = dict(environment['binding'])
        self.view = environment['policy_view']
        self.request = str(self.view.get('query') or '')
        self.tools = [t for t in self.view.get('tools') or [] if isinstance(t, dict) and isinstance(t.get('function'), dict) and isinstance(t['function'].get('name'), str)]
        self.schemas = {t['function']['name']: t['function'].get('parameters') if isinstance(t['function'].get('parameters'), dict) else {'type': 'object', 'properties': {}} for t in self.tools}
        steps = _count(self.view.get('max_steps'))
        if steps is None and isinstance(self.view.get('max_steps'), float):
            steps = int(self.view['max_steps'])
        self.max_steps = steps if steps and steps > 0 else 30
        self.started = time.monotonic()
        self.step = 0
        self.finished = bool(self.view.get('finished'))
        self.broke = False
        self.no_credit = False
        self.waited = 0
        self.misses = 0
        self.cost = 0.0
        self.calls = 0
        self.loop_calls = 0
        self.trace: list[dict[str, Any]] = []
        self.brief: dict[str, Any] = {}
        self.roles: dict[str, str] = {}
        self.items: list[Item] = []
        self.budget: Any = None
        self.msg_limit = 0
        self.msg_used = 0
        self.process: list[dict[str, Any]] = []
        self.reserve = 0
        self.gate_msgs = 0
        self.gate_ok: set[tuple[str, str]] = set()
        self.done_log: list[str] = []
        self.done_steps: list[int] = []
        self.asked = False
        self.qa: list[tuple[str, str]] = []
        self.rows: dict[str, dict[str, Any]] = {}
        self.full: dict[str, dict[str, Any]] = {}
        self.seen_order: list[str] = []
        self.heard: set[str] = set()
        self.notes: list[str] = []
        self.version = 0
        self.cart_touched = False
        self.cart_at = -1
        self.cart_seen_at = -1
        self.cart_view: Any = None
        self.note_named = False
        self.cart_lines: dict[str, int] = {}
        self.checked: set[str] = set()
        self.audited = False
        self.offer_seen: dict[str, int] = {}
        self.gone: dict[str, int] = {}
        self.unavailable: set[str] = set()
        self.sold_lines: set[str] = set()
        self.note_sold = False
        self.held = 0
        self.id_args: set[tuple[str, str]] = set()
        self.cart_said = ''
        self.refused_at = -1
        self.leads: list[str] = []
        self.refuse_blocks = 0
        self.pushed = False
        self.built: list[str] = []
        self.dropped: set[str] = set()
        self.late_held = False
        self.lead_items: dict[str, list[str]] = {}
        self.verdicts: dict[str, bool] = {}
        self.confirmed: str | None = None
        self.completed = False
        self.link_tried: set[str] = set()
        self.adopted: dict[str, int] = {}
        self.capped: set[tuple[str, float]] = set()
        self.id_key: str | None = None
        self.facts_from: dict[str, bool] = {}
        self.queued: list[str] = []
        self.buys = 0
        self.refusals = 0
        self.recent: list[str] = []
        self.chat: list[dict[str, Any]] = []
        self.opened: set[str] = set()
        self.refs: list[tuple[int, str]] = []
        self.ref_values: dict[str, str] = {}
        self.trails = 0
        self.trail_blocks = 0
        self.compare_ok = 0
        self.compare_bad = 0
        self.tool_keys: dict[str, set[str]] = {}
        self.view_keys: dict[str, tuple[int, set[str]]] = {}
        self.read_cache: dict[str, tuple[int, int, str]] = {}
        self.pages_read = 0
        self.shapes: dict[str, dict[str, Any] | None] = {}
        self.price_key: str | None = None
        self.stock_key: str | None = None
        self.cheaper_marks: set[str] = set()
        self.wider_held = False
        self.paged_obs: list[Any] = []
        self.plan_order: list[int] = []
        self.queues: dict[int, list[str]] = {}
        self.marks: dict[tuple[int, str], str] = {}
        self.item_misses: dict[int, int] = {}
        self.revealed_on: dict[int, int] = {}
